const dns = require('dns');

function checkSubdomainExists(subdomain, domain) {
  const fullDomain = `${subdomain}.${domain}`;
  return new Promise((resolve) => {
    dns.resolve(fullDomain, (err, addresses) => {
      if (err) {
        resolve(false);
      } else {
        resolve(!!addresses.length);
      }
    });
  });
}

// Example usage
checkSubdomainExists('subdomain', 'example.com')
  .then(exists => console.log(`Subdomain exists: ${exists}`));

